import{_ as e,c as a,o as s,ag as o}from"./chunks/framework.DCv_I274.js";const g=JSON.parse('{"title":"The web development workflow","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/web-development-workflow.md","filePath":"fundamentals/web-development-workflow.md","lastUpdated":null}'),i={name:"fundamentals/web-development-workflow.md"};function d(n,t,r,l,h,p){return s(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="the-web-development-workflow" tabindex="-1">The web development workflow <a class="header-anchor" href="#the-web-development-workflow" aria-label="Permalink to &quot;The web development workflow&quot;">​</a></h1><p>The tools and habits you use every day, whatever the framework.</p><h2 id="your-toolbox" tabindex="-1">Your toolbox <a class="header-anchor" href="#your-toolbox" aria-label="Permalink to &quot;Your toolbox&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it&#39;s for</th><th>Recommended</th></tr></thead><tbody><tr><td>Code editor</td><td>writing code</td><td>VS Code with the <strong>PHP Intelephense</strong>, <strong>Laravel</strong> and <strong>Vue/Volar</strong> extensions (or PhpStorm)</td></tr><tr><td>Terminal</td><td>running commands</td><td>Windows Terminal (PowerShell), or the terminal inside VS Code</td></tr><tr><td>Git</td><td>version history, teamwork</td><td>Git + GitHub / GitLab</td></tr><tr><td>PHP</td><td>runs the backend</td><td>PHP 8.3+ (installed by Herd or Laragon)</td></tr><tr><td>Composer</td><td>PHP package manager</td><td>installed with PHP</td></tr><tr><td>Node.js + npm</td><td>frontend build tools (Vite), these docs</td><td>current LTS</td></tr><tr><td>Database server + client</td><td>storing and inspecting data</td><td>MySQL 8 + HeidiSQL, TablePlus or DBeaver</td></tr><tr><td>HTTP client</td><td>calling your API by hand</td><td>VS Code <strong>REST Client</strong> extension (<code>.http</code> files), Postman, or Bruno</td></tr><tr><td>Browser DevTools</td><td>inspecting requests, cookies, console errors</td><td>F12 in Chrome / Edge / Firefox</td></tr></tbody></table><p>Installing them: <a href="/start/prerequisites">Prerequisites</a>.</p><h2 id="package-managers" tabindex="-1">Package managers <a class="header-anchor" href="#package-managers" aria-label="Permalink to &quot;Package managers&quot;">​</a></h2><p>You rarely write everything yourself; you install <strong>packages</strong>.</p><table tabindex="0"><thead><tr><th></th><th>PHP</th><th>JavaScript</th></tr></thead><tbody><tr><td>Tool</td><td>Composer</td><td>npm</td></tr><tr><td>List of packages</td><td><code>composer.json</code></td><td><code>package.json</code></td></tr><tr><td>Exact installed versions</td><td><code>composer.lock</code></td><td><code>package-lock.json</code></td></tr><tr><td>Installed files</td><td><code>vendor/</code></td><td><code>node_modules/</code></td></tr><tr><td>Add a package</td><td><code>composer require vendor/package</code></td><td><code>npm install package</code></td></tr><tr><td>Install everything after cloning</td><td><code>composer install</code></td><td><code>npm install</code></td></tr></tbody></table><ul><li><strong>Commit</strong> <code>composer.json</code>, <code>composer.lock</code>, <code>package.json</code>, <code>package-lock.json</code>.</li><li><strong>Never commit</strong> <code>vendor/</code> or <code>node_modules/</code>: they are rebuilt from the lock files.</li></ul><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to &quot;Environments&quot;">​</a></h2><p>The same code runs in several places with different settings:</p><table tabindex="0"><thead><tr><th>Environment</th><th>Who uses it</th><th>Typical settings</th></tr></thead><tbody><tr><td><strong>local</strong></td><td>you, on your computer</td><td><code>APP_DEBUG=true</code>, local database, fake mail</td></tr><tr><td><strong>staging</strong></td><td>testers, before release</td><td>like production, test data</td></tr><tr><td><strong>production</strong></td><td>real users</td><td><code>APP_DEBUG=false</code>, HTTPS, real mail, backups</td></tr></tbody></table><p>Settings that change per environment live in the <strong><code>.env</code></strong> file, which is <strong>never committed</strong>. A <code>.env.example</code> with safe placeholder values is committed so teammates know what to fill in. See <a href="/laravel-basics/config-and-env">Config &amp; environment</a>.</p><h2 id="git-basics" tabindex="-1">Git basics <a class="header-anchor" href="#git-basics" aria-label="Permalink to &quot;Git basics&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # get a copy of a repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/campus</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # start a branch for your work</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # what changed?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # stage changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Add campus module&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/campus</span></span></code></pre></div><p>Then open a <strong>pull request</strong> so a teammate reviews the change before it is merged into <code>main</code>.</p><p>Good habits:</p><ul><li>One branch per feature or fix; small, focused commits.</li><li>Commit messages say <em>what</em> and <em>why</em>: <code>Add campus module with permissions</code>, not <code>update</code>.</li><li>Pull <code>main</code> often to avoid big conflicts.</li><li>Never commit secrets (<code>.env</code>, private keys). If you do, <strong>rotate them</strong>: deleting the commit is not enough.</li></ul><h2 id="the-development-loop" tabindex="-1">The development loop <a class="header-anchor" href="#the-development-loop" aria-label="Permalink to &quot;The development loop&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> write code ─► run it ─► check it (browser / .http / tests) ─► read errors ─► fix</span></span>
<span class="line"><span>      ▲                                                                         │</span></span>
<span class="line"><span>      └─────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>Where to look when something breaks:</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Look at</th></tr></thead><tbody><tr><td>API returns 500</td><td><code>storage/logs/laravel.log</code>, and the <code>message</code> field when <code>APP_DEBUG=true</code></td></tr><tr><td>API returns 422</td><td>the <code>message</code>: validation told you what&#39;s wrong</td></tr><tr><td>&quot;Route not found&quot; / 404</td><td><code>php artisan route:list</code></td></tr><tr><td>Old config still used</td><td><code>php artisan optimize:clear</code></td></tr><tr><td>Frontend call fails</td><td>DevTools → Network (status, response) and Console (CORS errors)</td></tr><tr><td>Wrong data</td><td>your database client: look at the actual rows</td></tr></tbody></table><p>Debug helpers: <code>dd($value)</code> (dump and stop), <code>dump($value)</code>, <code>logger(&#39;message&#39;, [&#39;context&#39; =&gt; $x])</code>, and <code>php artisan tinker</code> to run PHP against your app interactively.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Automated tests are code that checks your code. They let you change things without fear:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>See <a href="/laravel-basics/testing">Testing with Pest</a>.</p><p>Next: <a href="/fundamentals/databases-and-sql">Databases &amp; SQL</a></p>`,28)])])}const k=e(i,[["render",d]]);export{g as __pageData,k as default};
